 			if (globe) {
 				globe.destroy()
 			}
 			onResize()
 		})
 		resizeObserver.observe(canvasRef.current)

 		return () => {
 			clearInterval(timer)
 			clearTimeout(timeoutId)
 			if (globe) {
 				globe.destroy()
 			}
 			resizeObserver.disconnect()
