 					<div className="grid-item mb-0 h-[236px] w-full p-2 md:w-1/2">
 						<LocationWidget />
 					</div>

 					{/* Build Status - 1 unit */}
 					<div className="grid-item mb-0 h-[236px] w-full p-2 md:w-1/4">
 						<BuildStatusWidget />
 					</div>

 					{/* GitHub - 2 units */}
 					<div className="grid-item mb-0 h-59 w-full p-2 md:w-1/2">
 						<GithubWidget />
 					</div>

 					{/* Uptime - 2 units */}
 					<div className="grid-item mb-0 h-59 w-full p-2 md:w-1/2">
 						<UptimeWidget />
 					</div>
 				</div>
 			</Container>
 		</section>
 	)
 }

