 export function WidgetDataProvider({ children }: { children: ReactNode }) {
 	const [data, setData] = useState<WidgetData>({
 		wakatime: null,
 		weather: null,
 		commits: null,
 		buildStatus: null,
 		opsStats: null,
 		loading: {
 			wakatime: true,
 			weather: true,
 			commits: true,
 			buildStatus: true,
 			opsStats: true,
 		},
 	})

 	useEffect(() => {
 		// Fetch WakaTime data
 		const fetchWakaTime = async () => {
 			try {
 				const response = await fetch("/api/wakatime")
 				if (response.ok) {
 					const wakatime = await response.json()
 					setData((prev) => ({
 						...prev,
 						wakatime,
